import { describe, test, expect } from "vitest";
import { parse, stringify } from "../src/index.js";

describe("path-to-regexp regression - astral ID_Continue", () => {
  test("stringify quotes param name followed by astral ID_Continue (parameter)", () => {
    // \u{1D6FC} is an astral character that is ID_Continue
    const tokens = parse("/:test\u{1D6FC}");
    const str = stringify(tokens);
    console.log("str =", JSON.stringify(str));
    // After parse, we expect tokens for [/, :test, 𝛼]
    // After stringify, the param name should be quoted because 𝛼 is ID_Continue
    expect(str).toBe('/:"test"\u{1D6FC}');
  });
  test("round-trip parse/stringify works", () => {
    const original = '/:"test"\u{1D6FC}';
    const tokens = parse(original);
    const str = stringify(tokens);
    const tokens2 = parse(str);
    expect(tokens2.tokens).toEqual(tokens.tokens);
  });
});

