import { describe, test, expect } from "vitest";
import { parse, stringify, TokenData } from "../src/index.js";

describe("path-to-regexp regression - astral ID_Continue", () => {
  test("stringify quotes param name followed by astral ID_Continue", () => {
    // \u{1D6FC} is an astral character that is ID_Continue
    const tokens = new TokenData([
      { type: "text", value: "/" },
      { type: "param", name: "test" },
      { type: "text", value: "\u{1D6FC}" },
    ]);
    const str = stringify(tokens);
    console.log("str =", JSON.stringify(str));
    // The param name should be quoted because 𝛼 is ID_Continue
    expect(str).toBe('/:"test"\u{1D6FC}');
  });
  test("round-trip parse/stringify works", () => {
    const original = '/:"test"\u{1D6FC}';
    const tokens = parse(original);
    const str = stringify(tokens);
    console.log("round-trip str =", JSON.stringify(str));
    const tokens2 = parse(str);
    expect(tokens2.tokens).toEqual(tokens.tokens);
  });
  test("stringify quotes wildcard name followed by astral ID_Continue", () => {
    const tokens = new TokenData([
      { type: "text", value: "/" },
      { type: "wildcard", name: "test" },
      { type: "text", value: "\u{1D6FC}" },
    ]);
    const str = stringify(tokens);
    expect(str).toBe('/*"test"\u{1D6FC}');
  });
});

